public enum IdType {
    AUTO(0),       // 数据库自增
    NONE(1),       // 无策略，跟随全局
    INPUT(2),      // 手动输入
    ASSIGN_ID(3),  // 雪花算法（默认）
    ASSIGN_UUID(4) // UUID
}
